import{_ as t,c as n,o as a,ag as r}from"./chunks/framework.CB_NIqHd.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/EngX_Quality/Could_please_the_differentiate_between_Functional_and_Non-functional_reqs(NFRs),_How_and_when_to_take_them_into_consideration.md","filePath":"senior_growth/EngX_Quality/Could_please_the_differentiate_between_Functional_and_Non-functional_reqs(NFRs),_How_and_when_to_take_them_into_consideration.md"}'),i={name:"senior_growth/EngX_Quality/Could_please_the_differentiate_between_Functional_and_Non-functional_reqs(NFRs),_How_and_when_to_take_them_into_consideration.md"};function s(o,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h3 id="could-you-please-the-differentiate-between-functional-and-non-functional-reqs-nfrs-how-and-when-to-take-them-into-consideration" tabindex="-1">Could you please the differentiate between Functional and Non-functional reqs(NFRs)? How and when to take them into consideration? <a class="header-anchor" href="#could-you-please-the-differentiate-between-functional-and-non-functional-reqs-nfrs-how-and-when-to-take-them-into-consideration" aria-label="Permalink to “Could you please the differentiate between Functional and Non-functional reqs(NFRs)? How and when to take them into consideration?”">​</a></h3><h3 id="functional-vs-non-functional-requirements" tabindex="-1"><strong>Functional vs. Non-Functional Requirements</strong> <a class="header-anchor" href="#functional-vs-non-functional-requirements" aria-label="Permalink to “Functional vs. Non-Functional Requirements”">​</a></h3><p>Both <strong>functional</strong> and <strong>non-functional requirements (NFRs)</strong> are critical in the software development process, but they focus on different aspects of the system. Here&#39;s a detailed comparison:</p><hr><h3 id="_1-functional-requirements" tabindex="-1"><strong>1. Functional Requirements</strong> <a class="header-anchor" href="#_1-functional-requirements" aria-label="Permalink to “1. Functional Requirements”">​</a></h3><h3 id="definition" tabindex="-1"><strong>Definition</strong> <a class="header-anchor" href="#definition" aria-label="Permalink to “Definition”">​</a></h3><p>Functional requirements define <strong>what the system should do</strong>. They describe the core features and functionalities of the application, specifying the behavior of the system under certain conditions.</p><h3 id="examples" tabindex="-1"><strong>Examples</strong> <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h3><ul><li>User authentication (login, logout, registration).</li><li>Ability to add, edit, delete, or retrieve data (CRUD operations).</li><li>Payment processing and order management.</li><li>Search functionality with filters.</li><li>Generating reports or exporting data.</li></ul><h3 id="characteristics" tabindex="-1"><strong>Characteristics</strong> <a class="header-anchor" href="#characteristics" aria-label="Permalink to “Characteristics”">​</a></h3><ul><li><strong>Action-Oriented</strong>: Focus on tasks the system must perform.</li><li><strong>Specific</strong>: Clearly defined actions and outputs for given inputs.</li><li><strong>Use Case Driven</strong>: Often derived from user stories or workflows.</li></ul><h3 id="when-to-consider" tabindex="-1"><strong>When to Consider</strong> <a class="header-anchor" href="#when-to-consider" aria-label="Permalink to “When to Consider”">​</a></h3><ul><li>During the initial phases of project planning and requirements gathering.</li><li>To ensure the app meets the core business objectives and user needs.</li><li>In writing use cases, user stories, and acceptance criteria.</li></ul><hr><h3 id="_2-non-functional-requirements-nfrs" tabindex="-1"><strong>2. Non-Functional Requirements (NFRs)</strong> <a class="header-anchor" href="#_2-non-functional-requirements-nfrs" aria-label="Permalink to “2. Non-Functional Requirements (NFRs)”">​</a></h3><h3 id="definition-1" tabindex="-1"><strong>Definition</strong> <a class="header-anchor" href="#definition-1" aria-label="Permalink to “Definition”">​</a></h3><p>NFRs define <strong>how the system should perform</strong>. They describe the quality attributes, constraints, and system behavior under specific conditions.</p><h3 id="examples-1" tabindex="-1"><strong>Examples</strong> <a class="header-anchor" href="#examples-1" aria-label="Permalink to “Examples”">​</a></h3><ul><li><strong>Performance</strong>: The system must handle 10,000 concurrent users with a response time of &lt;1 second.</li><li><strong>Scalability</strong>: The app should scale horizontally to accommodate traffic spikes.</li><li><strong>Security</strong>: User data must be encrypted both in transit and at rest.</li><li><strong>Usability</strong>: The app should be accessible to users with disabilities (e.g., WCAG compliance).</li><li><strong>Availability</strong>: The system should maintain 99.9% uptime.</li><li><strong>Maintainability</strong>: Code should follow defined coding standards and be easy to refactor.</li><li><strong>Portability</strong>: The app must run on Windows, MacOS, and Linux.</li></ul><h3 id="characteristics-1" tabindex="-1"><strong>Characteristics</strong> <a class="header-anchor" href="#characteristics-1" aria-label="Permalink to “Characteristics”">​</a></h3><ul><li><strong>System-Oriented</strong>: Focus on how the system behaves and performs.</li><li><strong>Verifiable</strong>: Quality goals need explicit measures, workload, environment and acceptance evidence; a vague adjective is not an acceptance criterion.</li><li><strong>Cross-Cutting</strong>: Apply across multiple features or the entire system.</li></ul><h3 id="when-to-consider-1" tabindex="-1"><strong>When to Consider</strong> <a class="header-anchor" href="#when-to-consider-1" aria-label="Permalink to “When to Consider”">​</a></h3><ul><li><strong>Early in the design phase</strong>: Architectural decisions like choosing tech stacks and frameworks are influenced by NFRs.</li><li><strong>Continuously throughout development</strong>: To ensure compliance with performance, security, and scalability goals.</li><li><strong>During testing</strong>: To validate metrics like load times, uptime, and accessibility.</li></ul><hr><h3 id="comparison-table" tabindex="-1"><strong>Comparison Table</strong> <a class="header-anchor" href="#comparison-table" aria-label="Permalink to “Comparison Table”">​</a></h3><table tabindex="0"><thead><tr><th><strong>Aspect</strong></th><th><strong>Functional Requirements</strong></th><th><strong>Non-Functional Requirements (NFRs)</strong></th></tr></thead><tbody><tr><td><strong>Focus</strong></td><td>What the system should do</td><td>How the system should perform</td></tr><tr><td><strong>Examples</strong></td><td>Login, search, data processing</td><td>Performance, security, scalability</td></tr><tr><td><strong>Measurement</strong></td><td>Based on behavior or actions</td><td>Based on quality metrics</td></tr><tr><td><strong>Impact on Design</strong></td><td>Drives application features</td><td>Drives architectural and operational decisions</td></tr><tr><td><strong>Testing</strong></td><td>Validated with functional testing (e.g., unit, integration)</td><td>Validated with performance, security, or stress testing</td></tr><tr><td><strong>Importance</strong></td><td>Addresses user and business needs</td><td>Ensures the system is reliable, efficient, and user-friendly</td></tr></tbody></table><hr><h3 id="how-and-when-to-take-them-into-consideration" tabindex="-1"><strong>How and When to Take Them into Consideration</strong> <a class="header-anchor" href="#how-and-when-to-take-them-into-consideration" aria-label="Permalink to “How and When to Take Them into Consideration”">​</a></h3><h3 id="_1-during-requirements-gathering" tabindex="-1"><strong>1. During Requirements Gathering</strong> <a class="header-anchor" href="#_1-during-requirements-gathering" aria-label="Permalink to “1. During Requirements Gathering”">​</a></h3><ul><li><strong>Functional Requirements</strong>: Engage stakeholders (e.g., product owners, business analysts) to gather user stories, use cases, and workflows.</li><li><strong>NFRs</strong>: Work with architects, DevOps engineers, and compliance teams to identify quality goals and constraints.</li></ul><h3 id="_2-during-architecture-and-design" tabindex="-1"><strong>2. During Architecture and Design</strong> <a class="header-anchor" href="#_2-during-architecture-and-design" aria-label="Permalink to “2. During Architecture and Design”">​</a></h3><ul><li>Define how the system will achieve both functional goals (features) and non-functional goals (e.g., performance, reliability).</li><li>Select tech stacks, frameworks, and tools that support NFRs (e.g., load balancers for scalability, encryption libraries for security).</li></ul><h3 id="_3-prioritize-requirements" tabindex="-1"><strong>3. Prioritize Requirements</strong> <a class="header-anchor" href="#_3-prioritize-requirements" aria-label="Permalink to “3. Prioritize Requirements”">​</a></h3><ul><li>Use techniques like <strong>MoSCoW (Must Have, Should Have, Could Have, Won’t Have)</strong> to ensure critical functional and non-functional requirements are addressed early.</li></ul><h3 id="_4-during-development" tabindex="-1"><strong>4. During Development</strong> <a class="header-anchor" href="#_4-during-development" aria-label="Permalink to “4. During Development”">​</a></h3><ul><li>Ensure functional requirements are implemented as specified in user stories or documentation.</li><li>Continuously validate NFRs using automated tests, code reviews, and adherence to coding standards.</li></ul><h3 id="_5-during-testing-and-validation" tabindex="-1"><strong>5. During Testing and Validation</strong> <a class="header-anchor" href="#_5-during-testing-and-validation" aria-label="Permalink to “5. During Testing and Validation”">​</a></h3><ul><li><strong>Functional Testing</strong>: Validate that features meet user requirements.</li><li><strong>Non-Functional Testing</strong>: Perform performance testing (e.g., stress, load testing), security audits, and usability testing.</li></ul><h3 id="_6-post-deployment" tabindex="-1"><strong>6. Post-Deployment</strong> <a class="header-anchor" href="#_6-post-deployment" aria-label="Permalink to “6. Post-Deployment”">​</a></h3><ul><li>Monitor NFRs like availability, performance, and scalability using tools like New Relic, Datadog, or Prometheus.</li><li>Gather user feedback to refine both functional and non-functional aspects.</li></ul><hr><h3 id="key-takeaways" tabindex="-1"><strong>Key Takeaways</strong> <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to “Key Takeaways”">​</a></h3><ul><li>Functional requirements are <strong>feature-focused</strong>, while NFRs are <strong>quality-focused</strong>.</li><li>Both are equally important—functional requirements ensure the app meets user needs, and NFRs ensure it performs reliably under real-world conditions.</li><li>Addressing NFRs early prevents costly architectural changes later in the development lifecycle.</li></ul><h2 id="quality-scenarios-and-acceptance-evidence" tabindex="-1">Quality scenarios and acceptance evidence <a class="header-anchor" href="#quality-scenarios-and-acceptance-evidence" aria-label="Permalink to “Quality scenarios and acceptance evidence”">​</a></h2><p>The examples above are starting points, not complete specifications. “10,000 concurrent users below one second” needs request mix, arrival rate, payload sizes, cache state, device/network, percentile, timeout/error treatment and measurement window. “99.9% uptime” needs an eligible-request denominator, success definition, observation window and exclusions agreed in advance. Encryption alone does not establish authorization; naming WCAG does not establish conformance. Functional and quality requirements overlap: a security invariant can be tested as observable behavior, and both influence architecture.</p><p>Use: <strong>stakeholder → stimulus → environment → affected component → response → measurable criterion</strong>. Agree on thresholds before implementation, keep failures in the denominator, and record measured results separately from intended targets.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Design decision and acceptance criterion</th><th>Evidence and remaining check</th></tr></thead><tbody><tr><td>User submits B while earlier query A is delayed</td><td>Epoch plus abort ownership; only the newest accepted query renders, even if A ignores abort</td><td><a href="./Large_Data_Workflow.html">Worked workflow</a> deferred-response test passed; real adapter still needs integration</td></tr><tr><td>User requests another page in a large catalogue</td><td>One native page, stable IDs and snapshot-bound server cursors; accept no more than 50 rows, no more than 100 selected IDs</td><td>Schema rejects 51 rows; fixture proves page replacement and selection retention. Cross-page selection cap and server cursor authorization remain learner tests</td></tr><tr><td>User restores filters on a shared device</td><td>Explicit, scoped, versioned intent only; fetch fresh first page and reject bad stored shape/version</td><td>Unicode/scope/version/oversized-storage fixture checks passed; shared-device policy and logout deletion must be implemented before enabling persistence</td></tr><tr><td>Catalogue changes during browsing</td><td>Server rejects expired/inconsistent snapshot; client shows recovery and clears selection</td><td>Mismatched-token client test passed; actual stable snapshot implementation is not supplied by a token alone</td></tr><tr><td>Keyboard user advances a page</td><td>Initial load preserves focus; user-requested accepted page focuses result heading and announces a status</td><td>DOM-focus check passed; native browser, screen reader, zoom and reflow observations still required</td></tr><tr><td>Product needs responsive results</td><td>Proposed page budget: 50 rows, agreed maximum response bytes and p95 interaction latency under a recorded workload</td><td>Set and measure byte/latency/heap budgets on specified hardware/network; no browser performance result is claimed</td></tr></tbody></table><p>The linked workflow contains an authored <strong>decision record</strong> with context, chosen pagination/persistence policy, alternatives and consequences. It is an actual design artifact for this fixture, not proof that a stakeholder approved it or a learner implemented it. Revisit the decision if users need arbitrary page jumps, editable rows, bulk selection or offline operation.</p><h3 id="practical-exercise" tabindex="-1">Practical exercise <a class="header-anchor" href="#practical-exercise" aria-label="Permalink to “Practical exercise”">​</a></h3><p>Choose one feature and write three quality scenarios before coding. For each, record stakeholder, stimulus, load/environment, measurable response, architecture choice, cost/trade-off and exact verification method. Implement one negative test and one measurement. Retain raw results and reconcile failures against the original threshold; do not change the threshold after a failed run without recording the decision. Acceptance: all scenarios trace to tests/measurements, proposed versus observed values are visibly distinct, and remaining manual checks have an owner. Use the <a href="https://react.dev/reference/react/useEffect" target="_blank" rel="noreferrer">official React</a> and <a href="https://www.w3.org/WAI/tutorials/tables/" target="_blank" rel="noreferrer">WAI table guidance</a> when validating the example&#39;s lifecycle and semantics. Learner practice remains outstanding.</p>',50)])])}const m=t(i,[["render",s]]);export{g as __pageData,m as default};
